package io.github.polestarcn.companion;
import static org.junit.Assert.*;
import android.app.*;import android.content.*;import android.content.pm.*;import android.content.res.Configuration;import android.graphics.*;import android.graphics.drawable.*;import android.view.*;import android.widget.*;import java.io.*;import java.lang.reflect.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,qualifiers="w360dp-h780dp-mdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class AppIconsV088Test {
 private AppRegressionTest base;private MainActivity a;
 @Before public void start()throws Exception{base=new AppRegressionTest();base.start();Field f=AppRegressionTest.class.getDeclaredField("activity");f.setAccessible(true);a=(MainActivity)f.get(base);}
 @After public void stop(){AlertDialog d=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();if(d!=null)d.dismiss();base.stop();}
 private void invoke(String name)throws Exception{Method m=MainActivity.class.getDeclaredMethod(name);m.setAccessible(true);m.invoke(a);}
 private void oneLauncher(String style,String mode){PackageManager pm=a.getPackageManager();int enabled=0;for(String s:AppIcons.STYLES)for(String m:AppIcons.MODES){ComponentName name=AppIcons.component(a,s,m);boolean on=pm.getComponentEnabledSetting(name)==PackageManager.COMPONENT_ENABLED_STATE_ENABLED;if(on){enabled++;assertEquals(AppIcons.component(a,style,mode),name);}}assertEquals(1,enabled);assertNotEquals(PackageManager.COMPONENT_ENABLED_STATE_DISABLED,pm.getComponentEnabledSetting(new ComponentName(a,MainActivity.class)));}
 @Test public void everyChoiceKeepsExactlyOneLauncherAndMainActivityEnabled()throws Exception{for(String style:AppIcons.STYLES)for(String mode:AppIcons.MODES){assertTrue(AppIcons.select(a,style,mode));oneLauncher(style,mode);assertEquals(style,AppIcons.style(a));assertEquals(mode,AppIcons.mode(a));Intent launch=a.getPackageManager().getLaunchIntentForPackage(a.getPackageName());assertNotNull(launch);assertEquals(AppIcons.component(a,style,mode),launch.getComponent());ActivityInfo info=a.getPackageManager().getActivityInfo(launch.getComponent(),0);assertEquals(MainActivity.class.getName(),info.targetActivity);assertEquals(AppIcons.launcher(style,mode),info.icon);}}
 @Test @Config(sdk=35) public void androidFifteenUsesAtomicBatchWithoutDisablingTheMainActivity(){for(String style:AppIcons.STYLES)for(String mode:AppIcons.MODES){assertTrue(AppIcons.select(a,style,mode));oneLauncher(style,mode);}}
 @Test @Config(sdk=26) public void androidEightKeepsAWorkingLauncherAcrossChanges(){assertTrue(AppIcons.select(a,"red","night"));oneLauncher("red","night");assertTrue(AppIcons.select(a,"outline","auto"));oneLauncher("outline","auto");}
 @Test public void persistedChoiceRecoversDuplicateAliasAndInvalidPreferencesUseOutline(){assertTrue(AppIcons.select(a,"skid","night"));a.getPackageManager().setComponentEnabledSetting(AppIcons.component(a,"red","day"),PackageManager.COMPONENT_ENABLED_STATE_ENABLED,PackageManager.DONT_KILL_APP);AppIcons.sync(a);oneLauncher("skid","night");AppPreferences.set(a,"app_icon_style","invalid");AppPreferences.set(a,"app_icon_mode","invalid");AppIcons.sync(a);oneLauncher("outline","auto");assertFalse(AppIcons.select(a,"missing","day"));oneLauncher("outline","auto");}
 @Test public void pickerCancelDoesNotSaveAndApplyDoesNotSendVehicleCommand()throws Exception{invoke("appIconDialog");AlertDialog dialog=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();dialog.findViewById(android.R.id.content).findViewWithTag("app_icon_red").performClick();dialog.getButton(AlertDialog.BUTTON_NEGATIVE).performClick();assertEquals("outline",AppIcons.style(a));invoke("appIconDialog");dialog=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();dialog.findViewById(android.R.id.content).findViewWithTag("app_icon_skid").performClick();dialog.findViewById(android.R.id.content).findViewWithTag("app_icon_mode_night").performClick();dialog.getButton(AlertDialog.BUTTON_POSITIVE).performClick();org.robolectric.shadows.ShadowLooper.shadowMainLooper().idle();assertEquals("skid",AppIcons.style(a));assertEquals("night",AppIcons.mode(a));assertEquals(OperationState.NOT_SENT,VehicleCoordinator.get(a).operation);assertFalse(VehicleCoordinator.get(a).commandPending);assertFalse(a.isFinishing());oneLauncher("skid","night");}
 @Test public void defaultCampCaptionIsShortAndTitleMatchesNeighbor()throws Exception{VehicleCoordinator model=VehicleCoordinator.get(a);Field f=VehicleCoordinator.class.getDeclaredField("signedIn");f.setAccessible(true);f.setBoolean(model,true);model.selected=new io.github.polestarcn.companion.api.ChinaPolestarApi.VehicleInfo();model.selected.vin="V088-FIXTURE";model.snapshot=new VehicleSnapshot("Polestar 2","masked",63,230,65845,"空闲","全部关闭","全部关闭","已关闭","已上锁",System.currentTimeMillis(),"LIVE",false,"关闭","关闭");AppPreferences.set(a,"language","zh");UiSkin.set(a,UiSkin.PS_DEFAULT);invoke("render");View root=a.getWindow().getDecorView();root.measure(View.MeasureSpec.makeMeasureSpec(360,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(780,View.MeasureSpec.EXACTLY));root.layout(0,0,360,780);TextView camp=root.findViewWithTag("camp_button"),windows=root.findViewWithTag("windows_control_button");assertEquals("露营\n未开启",camp.getText().toString());assertEquals(windows.getTextSize(),camp.getTextSize(),.01f);assertFalse(camp.getText().toString().contains("托管"));assertTrue(CampModeManager.status(a).contains("托管"));}
 private Bitmap draw(Drawable d,int width,int height){Bitmap b=Bitmap.createBitmap(width,height,Bitmap.Config.ARGB_8888);d.setBounds(0,0,width,height);d.draw(new Canvas(b));return b;}
 @Test public void statusGlyphsAreMonochromeWithTransparentOutsideAndNotificationUsesSelection()throws Exception{Method method=ResidentService.class.getDeclaredMethod("notification",Context.class);method.setAccessible(true);for(String style:AppIcons.STYLES){AppIcons.select(a,style,"day");Notification n=(Notification)method.invoke(null,a);assertEquals(AppIcons.small(style),n.getSmallIcon().getResId());Bitmap b=draw(a.getDrawable(AppIcons.small(a)),96,96);int opaque=0;for(int y=0;y<96;y++)for(int x=0;x<96;x++){int c=b.getPixel(x,y);if(Color.alpha(c)>0){opaque++;assertEquals(255,Color.red(c));assertEquals(255,Color.green(c));assertEquals(255,Color.blue(c));}}assertTrue(opaque>200);assertEquals(0,Color.alpha(b.getPixel(0,0)));assertEquals(0,Color.alpha(b.getPixel(95,95)));b.recycle();}}
 @Test public void adaptiveForegroundsStayInsideSafeCircleAndDayNightModesActuallyDiffer(){for(String style:AppIcons.STYLES){for(String mode:AppIcons.MODES){AdaptiveIconDrawable icon=(AdaptiveIconDrawable)a.getDrawable(AppIcons.launcher(style,mode));Bitmap b=draw(icon.getForeground(),216,216);for(int y=0;y<216;y++)for(int x=0;x<216;x++)if(Color.alpha(b.getPixel(x,y))>8)assertTrue(style+" "+mode+" unsafe pixel "+x+"/"+y,Math.hypot(x-107.5,y-107.5)<=66);b.recycle();}AdaptiveIconDrawable day=(AdaptiveIconDrawable)a.getDrawable(AppIcons.launcher(style,"day")),night=(AdaptiveIconDrawable)a.getDrawable(AppIcons.launcher(style,"night"));Bitmap d=draw(day.getBackground(),108,108),n=draw(night.getBackground(),108,108);assertNotEquals(d.getPixel(54,54),n.getPixel(54,54));d.recycle();n.recycle();}}
 @Test public void autoIconResourcesFollowSystemWhileExplicitDayStaysLight(){Configuration configuration=new Configuration(a.getResources().getConfiguration());configuration.uiMode=(configuration.uiMode&~Configuration.UI_MODE_NIGHT_MASK)|Configuration.UI_MODE_NIGHT_YES;Context night=a.createConfigurationContext(configuration);for(String style:AppIcons.STYLES){AdaptiveIconDrawable auto=(AdaptiveIconDrawable)night.getDrawable(AppIcons.launcher(style,"auto")),explicit=(AdaptiveIconDrawable)night.getDrawable(AppIcons.launcher(style,"day"));Bitmap x=draw(auto.getBackground(),48,48),y=draw(explicit.getBackground(),48,48);assertTrue(Color.red(x.getPixel(24,24))<40);assertTrue(Color.red(y.getPixel(24,24))>220);x.recycle();y.recycle();}}
 @Test public void exportsActualIconCatalogAndPicker()throws Exception{File dir=new File("build/reports/previews/v088");dir.mkdirs();Bitmap b=Bitmap.createBitmap(1080,1220,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(b);c.drawColor(Color.rgb(236,238,241));Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);p.setColor(Color.rgb(28,29,31));p.setTextSize(38);p.setTypeface(Typeface.create("sans-serif",Typeface.BOLD));c.drawText("PSA ICONS V3",40,58,p);String[] styles=AppIcons.STYLES;for(int row=0;row<3;row++)for(int col=0;col<3;col++){int x=col*350+44,y=row*355+120;boolean status=row==2;String mode=row==0?"day":"night";p.setColor(status?Color.rgb(24,25,27):Color.TRANSPARENT);if(status)c.drawRoundRect(x,y,x+290,y+260,24,24,p);Drawable icon=a.getDrawable(status?AppIcons.small(styles[col]):AppIcons.launcher(styles[col],mode));icon.setBounds(x+(status?45:0),y+(status?30:0),x+(status?245:290),y+(status?230:290));icon.draw(c);p.setColor(Color.rgb(35,36,38));p.setTextSize(24);p.setTypeface(Typeface.create("sans-serif",Typeface.NORMAL));c.drawText((col+1)+" "+styles[col].toUpperCase()+" / "+(status?"STATUS":mode.toUpperCase()),x,y+325,p);}
  try(FileOutputStream out=new FileOutputStream(new File(dir,"icon-catalog.png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}try(FileOutputStream out=new FileOutputStream(new File(dir,"icon-catalog.jpg"))){b.compress(Bitmap.CompressFormat.JPEG,96,out);}b.recycle();invoke("appIconDialog");AlertDialog dialog=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();View v=((ScrollView)dialog.findViewById(android.R.id.content).findViewWithTag("app_icon_picker").getParent()).getChildAt(0);v.setBackgroundColor(PsaDesign.canvas(false));v.measure(View.MeasureSpec.makeMeasureSpec(340,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(720,View.MeasureSpec.AT_MOST));v.layout(0,0,v.getMeasuredWidth(),v.getMeasuredHeight());Bitmap image=Bitmap.createBitmap(v.getWidth()*2,v.getHeight()*2,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(image);canvas.scale(2,2);v.draw(canvas);try(FileOutputStream out=new FileOutputStream(new File(dir,"icon-picker.png"))){image.compress(Bitmap.CompressFormat.PNG,100,out);}image.recycle();}
}
